#include "../common.h"
static double score(const char*s){const double f[26]={8.2,1.5,2.8,4.3,12.7,2.2,2.0,6.1,7.0,.15,0.77,4.0,2.4,6.7,7.5,1.9,.1,6.0,6.3,9.1,2.8,1.0,2.4,.15,2.0,.07};double z=0;for(int i=0;s[i];i++)if(isalpha((unsigned char)s[i]))z+=f[toupper(s[i])-'A'];return z;}int main(void){char c[1000],p[1000];printf("Ciphertext: ");fgets(c,sizeof c,stdin);double best=-1;int ba=1,bb=0;for(int a=1;a<26;a++)if(gcdn(a,26)==1)for(int b=0;b<26;b++){int d=invn(a,26);for(int i=0;c[i];i++)p[i]=isalpha((unsigned char)c[i])?(char)('A'+modn(d*(toupper(c[i])-'A'-b),26)):c[i];p[strlen(c)]=0;double z=score(p);if(z>best){best=z;ba=a;bb=b;}}printf("Best estimated key: a=%d b=%d; candidate: ",ba,bb);int d=invn(ba,26);for(int i=0;c[i];i++)putchar(isalpha((unsigned char)c[i])?'A'+modn(d*(toupper(c[i])-'A'-bb),26):c[i]);}
